fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    if min_val > max_val {
        // If the lower bound is greater than the upper bound, return a vector filled with max_val
        return vec![max_val; arr.len()];
    }

    // Create a new vector to store the clipped values
    let mut result = Vec::with_capacity(arr.len());

    for &value in arr.iter() {
        // Clip the value to the range [min_val, max_val]
        let clipped_value = if value < min_val {
            min_val
        } else if value > max_val {
            max_val
        } else {
            value
        };
        result.push(clipped_value);
    }

    result
}